function approveRequest(requestId) {
    fetch(`/approve-request/${requestId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: 'Approved' })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            alert('Request approved!');
            // Refresh the notifications
            location.reload();
        } else {
            alert('Failed to approve request.');
        }
    });
}

function denyRequest(requestId) {
    fetch(`/approve-request/${requestId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: 'Denied' })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            alert('Request denied!');
            // Refresh the notifications
            location.reload();
        } else {
            alert('Failed to deny request.');
        }
    });
}

function flagRequest(requestId) {
    fetch(`/flag-request/${requestId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: 'Flagged', flagReason: 'Inappropriate content' })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            alert('Request flagged!');
            // Refresh the notifications
            location.reload();
        } else {
            alert('Failed to flag request.');
        }
    });
}
```

